from helpers import *
LU="Lucent's General Knowledge"; NG="NCERT Class 6 'The Earth Our Habitat' and Class 11 Fundamentals of Physical Geography"
def bp(b,t): return sv("Book practice, 60 minutes max",b+" "+t)
W=week(HRS,{"quant":["Number System","Simplification"],"reasoning":["Mathematical Operations","Matrix","Statement & Conclusion"],"english":["Sentence Improvement","Para Jumbles"],"ga":["Geography"]},
unit("Quant: Number system, HCF-LCM, simplification",[
 part("Part 1: Number system",
  [rd(RSA,"Chapters 'Numbers' and 'Divisibility'"),rd(KM,"Chapter 'Number System': first 15 solved questions")],
  ["Divisibility: 2 (last digit even), 3 (digit sum divisible by 3), 4 (last two digits), 5, 6 (2 and 3), 8 (last three digits), 9 (digit sum), 11 (difference of odd-place and even-place digit sums is 0 or a multiple of 11).",
   "Unit digit of a power: cycles of 4 for 2, 3, 7, 8; cycles of 2 for 4 and 9; 0, 1, 5, 6 never change. Divide the power by 4 and use the remainder (0 means the 4th number of the cycle).",
   "Number of factors of N = p^a × q^b is (a + 1)(b + 1). Sum of first n natural numbers = n(n + 1)/2; sum of first n odd numbers = n².",
   "Dividend = Divisor × Quotient + Remainder. Remainder of a sum or product = sum or product of the remainders, then reduced."],
  [ex("Unit digit of 7^45?","7","Cycle of 7 is 7, 9, 3, 1. 45 mod 4 = 1, so the first: 7."),
   ex("Is 528176 divisible by 11?","Yes","Digits at odd places 5 + 8 + 7 = 20, at even places 2 + 1 + 6 = 9. The difference is 11, so yes."),
   ex("Number of factors of 360?","24","360 = 2³ × 3² × 5, so (3 + 1)(2 + 1)(1 + 1) = 24."),
   ex("Remainder when 17 × 23 is divided by 5?","1","17 leaves 2, 23 leaves 3, 2 × 3 = 6 leaves 1.")],
  [bp(RSA,"'Numbers': first 40 questions."),sv("Previous-year questions","KM 'Number System': 25 questions, 45 seconds each."),sv("App drill",None,dr("quant","Number System",20,15))]),
 part("Part 2: HCF and LCM",
  [rd(RSA,"Chapter 'H.C.F. and L.C.M. of Numbers'"),rd(KM,"Chapter 'HCF and LCM': first 10 solved questions")],
  ["For two numbers: HCF × LCM = product of the numbers. HCF divides every number; LCM is divisible by every number.",
   "Greatest number that divides a, b, c leaving remainders r1, r2, r3 = HCF of (a − r1), (b − r2), (c − r3). Smallest number leaving the same remainder r = LCM + r.",
   "Bells ringing together again, or runners meeting again, after the LCM of their times.",
   "HCF of fractions = HCF of numerators ÷ LCM of denominators. LCM of fractions = LCM of numerators ÷ HCF of denominators."],
  [ex("HCF of 12 and 18 is 6. Find their LCM.","36","12 × 18 / 6 = 36."),
   ex("Greatest number that divides 70 and 52 leaving remainder 4 each?","6","HCF of (70 − 4) and (52 − 4) = HCF(66, 48) = 6."),
   ex("Smallest number which leaves remainder 2 when divided by 6, 8 and 12?","26","LCM = 24, plus 2 = 26."),
   ex("Three bells ring every 6, 8 and 12 minutes. After how long do they ring together?","24 minutes","LCM = 24.")],
  [bp(RSA,"'HCF and LCM': first 40 questions."),sv("Previous-year questions","KM 'HCF and LCM': 20 questions."),sv("App drill",None,dr("quant","Number System",20,15,"85%"))]),
 part("Part 3: Simplification and approximation",
  [rd(RSA,"Chapters 'Simplification', 'Square roots and cube roots', 'Surds and indices'"),rd(KM,"Chapter 'Simplification': first 15 solved questions")],
  ["BODMAS: Brackets (in the order ( ) { } [ ]), Of, Division, Multiplication, Addition, Subtraction. Do 'of' before division.",
   "Squares 1 to 30 and cubes 1 to 15 by heart. (a + b)² = a² + 2ab + b². a² − b² = (a + b)(a − b).",
   "Indices: a^m × a^n = a^(m + n); a^m ÷ a^n = a^(m − n); (a^m)^n = a^(mn); a^0 = 1.",
   "Approximation: round each number to a convenient value, calculate, pick the closest option. Do not compute exactly."],
  [ex("Simplify 18 ÷ 3 × 2 + 4.","16","18 ÷ 3 = 6, × 2 = 12, + 4 = 16."),
   ex("Value of (25)² − (24)²?","49","(25 + 24)(25 − 24) = 49."),
   ex("Value of 2^5 × 2^3 ÷ 2^6?","4","2^(5 + 3 − 6) = 2² = 4."),
   ex("Approximate 49.9 × 20.1 ÷ 5.","About 200","50 × 20 ÷ 5 = 200.")],
  [bp(RSA,"'Simplification': first 50 questions."),sv("Previous-year questions","KM 'Simplification': 30 questions, 30 seconds each."),sv("App drill",None,dr("quant","Simplification",20,12))])]),
unit("Reasoning: Mathematical operations, matrix, statement and conclusion",[
 part("Part 1: Mathematical operations",
  [rd(RV,"Chapter 'Mathematical Operations'"),rd(KR,"Chapter 'Mathematical Operations': first 15 questions")],
  ["Two kinds: (1) symbols replaced by other operations, (2) letters standing for operations. First rewrite the expression with the real signs, then apply BODMAS.",
   "Swap carefully: if '+' means '−' and '×' means '÷', change each sign once and do not change again.",
   "Do the substitution on a fresh line before calculating. Check one answer by plugging back."],
  [ex("If + means −, − means ×, × means ÷, find 8 + 6 − 3 × 3.","2","Rewrite: 8 − 6 × 3 ÷ 3. BODMAS: 6 × 3 ÷ 3 = 6, then 8 − 6 = 2."),
   ex("If A means +, B means −, find 12 A 8 B 5.","15","12 + 8 − 5 = 15."),
   ex("If 'a' means ×, 'b' means ÷, find 20 b 5 a 3.","12","20 ÷ 5 × 3 = 12.")],
  [bp(RV,"'Mathematical Operations': 30 questions (shorten to 40 min)."),sv("App drill",None,dr("reasoning","Mathematical Operations",15,10))]),
 part("Part 2: Matrix and missing number",
  [rd(RV,"Chapter 'Completing the Matrix' / 'Missing Number'"),rd(KR,"Chapter 'Missing Number': first 15 questions")],
  ["Check rows first, then columns, then diagonals. A common rule: third number = first + second, first × second, or first² + second.",
   "If a rule fails for one row, try a different operation on that row, but the same rule must work for all rows.",
   "Squares and cubes are common: 4, 9, 16, 25 and 8, 27, 64, 125 should be recognised instantly."],
  [ex("2 3 5; 4 6 10; 6 9 ?","15","Third = first + second."),ex("3 9 27; 2 4 8; 5 25 ?","125","x, x², x³."),ex("2 3 6; 4 5 20; 6 7 ?","42","Third = first × second.")],
  [bp(RV,"'Missing Number': 30 questions (shorten to 40 min)."),sv("App drill",None,dr("reasoning","Matrix",5,5))]),
 part("Part 3: Statement and conclusion",
  [rd(RV,"Chapter 'Statement and Conclusions'"),rd(KR,"Chapter 'Statement and Conclusion': first 15 questions")],
  ["A conclusion follows only if it is a certain consequence of the statement itself, not of your own knowledge.",
   "'All' to 'Some': All A are B gives Some B are A. 'Some' never gives 'All'.",
   "'Only' statements: Only students got the prize means every winner is a student.",
   "If both conclusions are doubtful and form a pair, the answer is 'Either I or II follows'."],
  [ex("All doctors are graduates. Conclusion: Some graduates are doctors.","Follows","Conversion of All."),ex("Some cars are red. Conclusion: All cars are red.","Does not follow","Some does not give All.")],
  [bp(RV,"'Statement and Conclusions': 30 questions (shorten to 40 min)."),sv("App drill",None,dr("reasoning","Statement & Conclusion",6,6))])]),
unit("English: Sentence improvement and para jumbles",[
 part("Part 1: Sentence improvement, common errors",
  [rd(SB,"Chapter 'Sentence Improvement'"),rd(WM,"Revise: prepositions and verbs sections")],
  ["Read the underlined part, then each option in the full sentence. Choose 'No improvement' only when the sentence is truly correct.",
   "Common traps: 'prefer … to' (not 'than'); 'senior/junior to'; 'hardly … when'; 'no sooner … than'; 'good at'; 'each/every + singular verb'.",
   "Stative verbs (know, want, like, belong, believe) are not used in continuous tenses."],
  [ex("Improve: He is senior than me.","senior to me","Senior/junior take 'to'."),ex("Improve: She prefers tea than coffee.","tea to coffee","Prefer … to."),ex("Improve: Each of the boys have a book.","Each of the boys has","Each takes a singular verb.")],
  [bp(SB,"'Sentence Improvement': 40 questions."),sv("App drill",None,dr("english","Sentence Improvement",8,8))]),
 part("Part 2: Sentence improvement, harder patterns",
  [rd(SB,"Sentence improvement: second exercise set"),rd(WM,"Chapter on conditionals and tenses")],
  ["Check subject-verb agreement, tense consistency, article use and word order together.",
   "Conditionals: If + past, would + verb (unreal). 'If I were you' not 'If I was you'.",
   "'News', 'mathematics', 'physics' look plural but are singular."],
  [ex("Improve: The news are good.","The news is good","'News' is singular."),ex("Improve: I have been knowing him for ten years.","I have known him","Stative verb, no continuous.")],
  [bp(SB,"'Sentence Improvement': another 40 questions."),sv("App drill",None,dr("english","Sentence Improvement",8,8,"85%"))]),
 part("Part 3: Para jumbles",
  [rd(SB,"Chapter 'Para Jumbles' / 'Sentence Arrangement'"),rd(WM,"Chapter on composition: linking words")],
  ["Find the opening sentence first: it introduces the subject and has no pronoun that needs an earlier noun.",
   "Look for mandatory pairs: noun then pronoun, 'however' after a point, question then answer.",
   "Linkers: however, but, yet = contrast; therefore, hence, so = result; also, moreover = addition; finally = end.",
   "Test your order by reading the whole paragraph once at the end."],
  [ex("Order: P the monsoon / Q arrives in June / R in Kerala / S usually.","P S Q R","The monsoon usually arrives in June in Kerala."),ex("Which comes first? (1) It then enters the sea. (2) The Ganga rises in the Himalayas. (3) It flows through the plains.","(2), (3), (1)","Source, journey, end.")],
  [bp(SB,"'Para Jumbles': 25 sets."),sv("App drill",None,dr("english","Para Jumbles",6,6))])]),
unit("GA: World geography",[
 part("Part 1: Earth, continents and oceans",
  [rd(NG,"Class 6 'The Earth in the Solar System', 'Globe: Latitudes and Longitudes', 'Motions of the Earth'"),rd(LU,"Geography: The Universe, the Earth")],
  ["Seven continents by size: Asia, Africa, North America, South America, Antarctica, Europe, Australia. Five oceans: Pacific (largest and deepest, Mariana Trench), Atlantic, Indian, Southern, Arctic (smallest).",
   "Equator 0°; Tropic of Cancer 23.5°N; Tropic of Capricorn 23.5°S; Prime Meridian 0° at Greenwich; International Date Line near 180°. Earth rotates west to east in 24 hours and revolves round the Sun in about 365¼ days.",
   "Longest river: Nile; largest hot desert: Sahara; highest peak: Everest (8,849 m); lowest point on land: Dead Sea shore."],
  [ex("Which is the smallest continent?","Australia"),ex("Where is the Mariana Trench?","Pacific Ocean"),ex("Which line passes through Greenwich?","Prime Meridian")],
  [sv("Map work","Outline the continents and oceans, mark the Equator, both tropics and the Prime Meridian."),sv("App drill",None,dr("ga","Geography",15,10))]),
 part("Part 2: Climate and winds",
  [rd(NG,"Class 11 Fundamentals of Physical Geography, chapters on atmosphere, winds and climate"),rd(LU,"Geography: Atmosphere, climate")],
  ["Layers of the atmosphere: Troposphere (weather), Stratosphere (ozone layer), Mesosphere, Thermosphere (ionosphere), Exosphere.",
   "Winds: trade winds blow towards the Equator, westerlies at 30-60° and polar easterlies. Monsoon = seasonal reversal of winds.",
   "Climate zones: tropical (hot, wet), arid desert, temperate, polar. Equatorial regions get rain all year (Amazon, Congo)."],
  [ex("In which layer does weather occur?","Troposphere"),ex("Which layer holds the ozone?","Stratosphere")],
  [sv("Make a table","Layer / Height / Famous for. Five rows."),sv("App drill",None,dr("ga","Geography",15,10,"85%"))]),
 part("Part 3: Resources, rivers and deserts of the world",
  [rd(LU,"World Geography: rivers, lakes, deserts, mountains"),rd(NG,"Class 7 Our Environment and Class 8 Resources and Development")],
  ["Rivers: Nile (longest, Egypt), Amazon (largest by volume), Yangtze (Asia), Mississippi, Danube. Lakes: Caspian (largest), Superior (largest freshwater by area), Baikal (deepest).",
   "Deserts: Sahara (Africa), Arabian, Gobi (Mongolia and China), Atacama (driest, Chile), Thar (India).",
   "Mountains: Himalayas (Asia), Andes (South America), Rockies (North America), Alps (Europe)."],
  [ex("Driest desert in the world?","Atacama"),ex("Deepest lake?","Lake Baikal")],
  [sv("Map work","Mark 6 rivers, 4 deserts, 4 mountain ranges on a world map."),sv("App drill",None,dr("ga","Geography",15,10))])])
)
add_week('p1','p1-w6',W)
